class ProfileFragment : Fragment(R.layout.fragment_profile) {

  // WRONG: this field outlives onDestroyView and pins the whole view tree
  // private lateinit var binding: FragmentProfileBinding

  private var _binding: FragmentProfileBinding? = null
  private val binding get() = checkNotNull(_binding) { "binding used outside the view lifecycle" }

  override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
    // bind(), not inflate() — the layout-id constructor already inflated it
    _binding = FragmentProfileBinding.bind(view)
    binding.saveButton.setOnClickListener { viewModel.save() }

    // viewLifecycleOwner, not the Fragment: the collector must die with the view
    viewLifecycleOwner.lifecycleScope.launch {
      viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
        viewModel.state.collect { binding.title.text = it.title }
      }
    }
  }

  override fun onDestroyView() {
    super.onDestroyView()
    _binding = null            // the one line that stops the leak
  }
}

