class MeterView @JvmOverloads constructor(
  context: Context, attrs: AttributeSet? = null, defStyleAttr: Int = 0
) : View(context, attrs, defStyleAttr) {

  private val paint = Paint(Paint.ANTI_ALIAS_FLAG)   // allocated once, not in onDraw
  private val bar = RectF()

  var progress: Float = 0f
    set(value) {
      field = value.coerceIn(0f, 1f)
      invalidate()          // pixels only — requestLayout() here relayouts the branch every frame
    }

  var label: String = ""
    set(value) {
      field = value
      requestLayout()       // the text can change the measured width, so this one earns it
      invalidate()
    }

  override fun onMeasure(widthSpec: Int, heightSpec: Int) {
    // A spec packs MeasureSpec.getMode() + MeasureSpec.getSize():
    //   EXACTLY     the parent decided (match_parent or a fixed dp)
    //   AT_MOST     no more than getSize() (wrap_content)
    //   UNSPECIFIED as big as you like (a ScrollView measuring its child)
    val naturalW = paddingLeft + paddingRight + paint.measureText(label).toInt()
    val naturalH = paddingTop + paddingBottom + BAR_HEIGHT

    // resolveSize applies the mode for you; forgetting this call throws IllegalStateException
    setMeasuredDimension(
      resolveSize(naturalW.coerceAtLeast(suggestedMinimumWidth), widthSpec),
      resolveSize(naturalH.coerceAtLeast(suggestedMinimumHeight), heightSpec)
    )
  }

  override fun onSizeChanged(w: Int, h: Int, oldw: Int, oldh: Int) {
    bar.set(paddingLeft.toFloat(), paddingTop.toFloat(),
            (w - paddingRight).toFloat(), (h - paddingBottom).toFloat())
  }

  override fun onDraw(canvas: Canvas) {
    canvas.drawRect(bar.left, bar.top, bar.left + bar.width() * progress, bar.bottom, paint)
  }

  private companion object { const val BAR_HEIGHT = 24 }
}

