class RatingView @JvmOverloads constructor(
  context: Context, attrs: AttributeSet? = null, defStyleAttr: Int = 0
) : View(context, attrs, defStyleAttr) {

  private val paint = Paint(Paint.ANTI_ALIAS_FLAG)
  private val content = RectF()
  var rating = 0
    set(value) { field = value; invalidate() }

  init {
    // use { } recycles the TypedArray (androidx.core:core-ktx)
    context.obtainStyledAttributes(attrs, R.styleable.RatingView, defStyleAttr, 0).use { a ->
      paint.color = a.getColor(R.styleable.RatingView_starColor, Color.YELLOW)
      rating = a.getInt(R.styleable.RatingView_rating, 0)
    }
  }

  override fun onSizeChanged(w: Int, h: Int, oldw: Int, oldh: Int) {
    // Padding is yours to honour: the canvas still starts at 0,0
    content.set(paddingStart.toFloat(), paddingTop.toFloat(),
                (w - paddingEnd).toFloat(), (h - paddingBottom).toFloat())
  }

  override fun onDraw(canvas: Canvas) {
    val step = content.width() / 5f
    for (i in 0 until rating) {
      canvas.drawCircle(content.left + step * (i + 0.5f), content.centerY(), step / 3f, paint)
    }
  }

  override fun onSaveInstanceState(): Parcelable =
    SavedState(super.onSaveInstanceState()).also { it.rating = rating }

  override fun onRestoreInstanceState(state: Parcelable?) {
    val saved = state as? SavedState ?: return super.onRestoreInstanceState(state)
    super.onRestoreInstanceState(saved.superState)   // give the base class its state back
    rating = saved.rating
  }

  private class SavedState : BaseSavedState {
    var rating = 0
    constructor(superState: Parcelable?) : super(superState)
    constructor(source: Parcel) : super(source) { rating = source.readInt() }
    override fun writeToParcel(out: Parcel, flags: Int) {
      super.writeToParcel(out, flags)
      out.writeInt(rating)
    }
    companion object CREATOR : Parcelable.Creator<SavedState> {
      override fun createFromParcel(source: Parcel) = SavedState(source)
      override fun newArray(size: Int) = arrayOfNulls<SavedState>(size)
    }
  }
}

class OrderAdapter(
  private val onClick: (Order) -> Unit
) : RecyclerView.Adapter<OrderAdapter.Holder>() {

  private val items = mutableListOf<Order>()

  class Holder(val binding: ItemOrderBinding) : RecyclerView.ViewHolder(binding.root)

  override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): Holder {
    // attachToRoot = false: the LayoutManager attaches the row, and parent supplies the LayoutParams
    val binding = ItemOrderBinding.inflate(LayoutInflater.from(parent.context), parent, false)
    val holder = Holder(binding)

    // Wired once per holder, not once per bind; the position is read at click time
    binding.root.setOnClickListener {
      val pos = holder.bindingAdapterPosition
      if (pos != RecyclerView.NO_POSITION) onClick(items[pos])
    }
    return holder
  }

  override fun onBindViewHolder(holder: Holder, position: Int) {
    val item = items[position]

    // WRONG: a new listener every bind, and a captured position that goes stale
    // holder.binding.root.setOnClickListener { onClick(items[position]) }
    // WRONG: an if with no else — the recycled row keeps the previous item's badge
    // if (item.isUrgent) holder.binding.badge.isVisible = true

    // RIGHT: every field assigned on every path
    holder.binding.title.text = item.title
    holder.binding.badge.isVisible = item.isUrgent
    holder.binding.thumb.setImageDrawable(null)   // clear before the async load resolves
    holder.binding.thumb.load(item.imageUrl)      // Coil cancels this ImageView's previous request
  }

  override fun getItemCount() = items.size
}

