class OrderAdapter : ListAdapter<Order, OrderAdapter.Holder>(DIFF) {

  override fun onBindViewHolder(holder: Holder, position: Int) {
    val item = getItem(position)
    holder.binding.title.text = item.title
    holder.binding.unread.text = item.unread.toString()
  }

  // Partial rebind: touches one view and leaves a running item animation alone
  override fun onBindViewHolder(holder: Holder, position: Int, payloads: MutableList<Any>) {
    if (payloads.isEmpty()) return super.onBindViewHolder(holder, position, payloads)
    holder.binding.unread.text = getItem(position).unread.toString()
  }

  class Holder(val binding: ItemOrderBinding) : RecyclerView.ViewHolder(binding.root)

  companion object {
    private const val PAYLOAD_UNREAD = "unread"

    private val DIFF = object : DiffUtil.ItemCallback<Order>() {
      // Identity: ids only. Comparing whole objects here turns every edit into remove + insert
      override fun areItemsTheSame(old: Order, new: Order) = old.id == new.id

      // Appearance: data-class equals, valid because Order is immutable
      override fun areContentsTheSame(old: Order, new: Order) = old == new

      // "only the unread count moved" -> rebind one TextView instead of the whole row
      override fun getChangePayload(old: Order, new: Order): Any? =
        if (old.copy(unread = new.unread) == new) PAYLOAD_UNREAD else null
    }
  }
}

