class RowVH(private val b: ItemRowBinding) : RecyclerView.ViewHolder(b.root) {

  // ❌ every stale-row symptom in five lines
  fun bindBad(row: Row, onToggle: (Int) -> Unit) {
    if (row.avatarUrl != null) b.avatar.load(row.avatarUrl)   // else the old photo stays
    b.check.setOnCheckedChangeListener { _, _ -> onToggle(bindingAdapterPosition) }
    b.check.isChecked = row.selected                          // fires the listener above
    b.root.animate().alpha(1f).setDuration(200).start()       // survives recycling half-done
  }

  // ✅ overwrite every field, detach before writing, read the position late
  fun bind(row: Row, onToggle: (Int) -> Unit) {
    b.avatar.load(row.avatarUrl) {
      placeholder(R.drawable.avatar_placeholder)   // never show the previous bitmap
      fallback(R.drawable.avatar_placeholder)      // the null case is a value too
    }
    b.check.setOnCheckedChangeListener(null)
    b.check.isChecked = row.selected
    b.check.setOnCheckedChangeListener { _, _ ->
      val pos = bindingAdapterPosition
      if (pos != RecyclerView.NO_POSITION) onToggle(pos)
    }
    b.title.text = row.title
    b.subtitle.isVisible = row.subtitle != null
    b.subtitle.text = row.subtitle.orEmpty()
  }
}

// In the adapter: the view's animation state is not part of the item
override fun onViewRecycled(holder: RowVH) {
  holder.itemView.animate().cancel()
  holder.itemView.alpha = 1f
  holder.itemView.translationX = 0f
}

sealed interface Row {
  val id: Long
  data class Header(override val id: Long, val title: String) : Row
  data class Article(override val id: Long, val headline: String) : Row
  data class Ad(override val id: Long, val slot: String) : Row
}

class FeedAdapter : ListAdapter<Row, RecyclerView.ViewHolder>(Diff) {

  // The type comes from the model — a new Row subtype fails to compile right here
  override fun getItemViewType(position: Int) = when (getItem(position)) {
    is Row.Header -> R.layout.item_header
    is Row.Article -> R.layout.item_article
    is Row.Ad -> R.layout.item_ad
  }

  override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
    val inflater = LayoutInflater.from(parent.context)
    return when (viewType) {
      R.layout.item_header -> HeaderVH(ItemHeaderBinding.inflate(inflater, parent, false))
      R.layout.item_article -> ArticleVH(ItemArticleBinding.inflate(inflater, parent, false))
      else -> AdVH(ItemAdBinding.inflate(inflater, parent, false))
    }
  }

  override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
    when (val row = getItem(position)) {
      is Row.Header -> (holder as HeaderVH).bind(row)
      is Row.Article -> (holder as ArticleVH).bind(row)
      is Row.Ad -> (holder as AdVH).bind(row)
    }
  }

  object Diff : DiffUtil.ItemCallback<Row>() {
    // two different subtypes are never the same item, whatever their ids say
    override fun areItemsTheSame(a: Row, b: Row) = a::class == b::class && a.id == b.id
    override fun areContentsTheSame(a: Row, b: Row) = a == b
  }
}

