class CarouselHost(ctx: Context, attrs: AttributeSet?) : FrameLayout(ctx, attrs) {
  private val slop = ViewConfiguration.get(ctx).scaledTouchSlop
  private var downX = 0f
  private var downY = 0f

  // Steal the gesture only once it is clearly horizontal — deciding on DOWN is the bug
  override fun onInterceptTouchEvent(ev: MotionEvent): Boolean = when (ev.actionMasked) {
    MotionEvent.ACTION_DOWN -> {
      downX = ev.x
      downY = ev.y
      false                                  // let the child see DOWN, keep watching
    }
    MotionEvent.ACTION_MOVE -> {
      val dx = abs(ev.x - downX)
      val dy = abs(ev.y - downY)
      dx > slop && dx > dy                   // true here: the child gets ACTION_CANCEL
    }
    else -> false
  }
}

// The child's half of the contract: claim the gesture for as long as it is yours
class SignaturePad(ctx: Context) : View(ctx) {
  override fun onTouchEvent(ev: MotionEvent): Boolean {
    when (ev.actionMasked) {
      MotionEvent.ACTION_DOWN -> parent.requestDisallowInterceptTouchEvent(true)
      MotionEvent.ACTION_UP,
      MotionEvent.ACTION_CANCEL -> parent.requestDisallowInterceptTouchEvent(false)
    }
    return true      // returning false for DOWN forfeits every later event of the gesture
  }
}

