class HideOnScrollBehavior(ctx: Context, attrs: AttributeSet?) :
  CoordinatorLayout.Behavior<FloatingActionButton>(ctx, attrs) {

  // Step 1: declare the axes you want, or you are simply not part of the scroll
  override fun onStartNestedScroll(
    parent: CoordinatorLayout, child: FloatingActionButton, directTargetChild: View,
    target: View, axes: Int, type: Int,
  ): Boolean = axes and ViewCompat.SCROLL_AXIS_VERTICAL != 0

  // Step 2: first refusal — consume here and the list has not scrolled yet
  override fun onNestedPreScroll(
    parent: CoordinatorLayout, child: FloatingActionButton, target: View,
    dx: Int, dy: Int, consumed: IntArray, type: Int,
  ) {
    if (type == ViewCompat.TYPE_TOUCH && abs(dy) > child.height / 4) {
      if (dy > 0) child.hide() else child.show()
    }
  }

  // Step 3: what the list could not use — this is how a parent reacts to an overscroll
  override fun onNestedScroll(
    parent: CoordinatorLayout, child: FloatingActionButton, target: View,
    dxConsumed: Int, dyConsumed: Int, dxUnconsumed: Int, dyUnconsumed: Int,
    type: Int, consumed: IntArray,
  ) {
    if (dyUnconsumed < 0) child.show()      // the list hit the top and could not scroll further
  }
}

