class ChatActivity : AppCompatActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()          // required below API 35; already the behaviour at 35+
    super.onCreate(savedInstanceState)
    setContentView(binding.root)

    // setStatusBarColor is deprecated and ignored when targeting 35+; control the icons instead
    WindowCompat.getInsetsController(window, window.decorView)
      .isAppearanceLightStatusBars = true

    ViewCompat.setOnApplyWindowInsetsListener(binding.toolbar) { v, insets ->
      val bars = insets.getInsets(
        WindowInsetsCompat.Type.systemBars() or WindowInsetsCompat.Type.displayCutout()
      )
      v.updatePadding(top = bars.top, left = bars.left, right = bars.right)
      insets           // ❌ WindowInsetsCompat.CONSUMED here starves every sibling below
    }

    // Rows scroll under the navigation bar, the last one stops above it
    binding.messages.clipToPadding = false
    ViewCompat.setOnApplyWindowInsetsListener(binding.messages) { v, insets ->
      v.updatePadding(bottom = insets.getInsets(WindowInsetsCompat.Type.systemBars()).bottom)
      insets
    }

    // The composer follows the keyboard when it is up, the navigation bar when it is not
    ViewCompat.setOnApplyWindowInsetsListener(binding.composer) { v, insets ->
      val ime = insets.getInsets(WindowInsetsCompat.Type.ime()).bottom
      val nav = insets.getInsets(WindowInsetsCompat.Type.systemBars()).bottom
      v.updatePadding(bottom = maxOf(ime, nav))
      insets
    }
  }
}

